def bina(l, r, c, d, ss, n):
	m = (l + r + 1) // 2
	if l == r:
		return l
	y = d // (m + 1)
	otv = ss[min(n - 1, m)] * y
	if (m + 1) * y < d:
		otv += ss[min(n, d - y * (m + 1)) - 1]
	if otv >= c:
		return bina(m, r, c, d, ss, n)
	else:
		return bina(l, m - 1, c, d, ss, n)
t = int(input())
for test in range(t):
	(n, c, d) = map(int, input().split())
	a = list(map(int, input().split()))
	a.sort(reverse=True)
	x = sum(a[:min(n, d)])
	if x >= c:
		print('Infinity')
	elif a[0] * d < c:
		print('Impossible')
	else:
		ss = [0] * n
		ss[0] = a[0]
		for i in range(1, n):
			ss[i] = ss[i - 1] + a[i]
		print(bina(0, d, c, d, ss, n))
